const fx={live:{layers:defaultLayers,pip:{on:false,source:0,size:28,corner:'top-right',fit:'contain',aspect:'16:9',border:'#ffffff'},logo:{on:false,corner:'top-left',size:10,opacity:100}},draft:null,logo:null,draftLogo:null};fx.draft=structuredClone(fx.live);
const effectsPage=document.createElement('section');effectsPage.className='workspace-page effects-page';pages.effects=effectsPage;configuration.after(effectsPage);const effectTab=document.createElement('button');effectTab.dataset.page='effects';effectTab.textContent='GC e efeitos';effectTab.onclick=()=>openWorkspace('effects');nav.append(effectTab);effectsPage.hidden=true;
