const corners='<option value="top-left">Superior esquerdo</option><option value="top-right">Superior direito</option><option value="bottom-left">Inferior esquerdo</option><option value="bottom-right">Inferior direito</option>';
effectsPage.innerHTML='<div class="effects-header"><div><h2>GC, logotipo e PiP</h2><p>Prepare os ajustes nesta página e clique em Aplicar. Na operação, os botões de camadas colocam e retiram cada elemento do AR.</p></div><button id="fxApply">Aplicar ajustes ao programa</button><button id="fxDiscard">Descartar ajustes</button></div><div class="effects-workbench"><div class="effects-editor"><section class="fx-card"><h3>Gerador de caracteres · camadas</h3><label>Camada <select id="fxLayer"></select></label><label><input id="gcOn" type="checkbox"> Ativar esta camada ao aplicar</label><label>Título / crédito<input id="gcTitle" maxlength="160" placeholder="Nome da pessoa ou título"></label><label>Subtítulo / legenda<textarea id="gcSubtitle" maxlength="240" rows="2" placeholder="Cargo, instituição ou texto de apoio"></textarea></label><label>Posição<select id="gcCorner">'+corners+'</select></label><label>Largura (%)<input id="gcWidth" type="range" min="30" max="94"></label><label>Tamanho do texto<input id="gcSize" type="range" min="22" max="64"></label><label>Opacidade do fundo<input id="gcOpacity" type="range" min="0" max="100"></label><div class="fx-colors"><label>Fundo<input id="gcBackground" type="color"></label><label>Texto<input id="gcColor" type="color"></label><label>Destaque<input id="gcAccent" type="color"></label></div><div><button id="gcBack">Mover camada para trás</button><button id="gcFront">Mover camada para frente</button></div><small>A ordem da lista é de baixo para cima. Camadas na mesma posição podem se cobrir.</small></section><section class="fx-card"><h3>Logotipo fixo</h3><label>Arquivo PNG, JPEG ou WebP<input id="logoFile" type="file" accept="image/png,image/jpeg,image/webp"></label><label><input id="logoOn" type="checkbox"> Ativar ao aplicar</label><label>Posição<select id="logoCorner">'+corners+'</select></label><label>Tamanho (%)<input id="logoSize" type="range" min="4" max="25"></label><label>Opacidade<input id="logoOpacity" type="range" min="0" max="100"></label><button id="logoRemove">Remover arquivo do rascunho</button><small>PNG/WebP com transparência preservam o fundo da transmissão.</small></section><section class="fx-card"><h3>DVE / Picture-in-Picture</h3><label><input id="pipOn" type="checkbox"> Ativar janela ao aplicar</label><label>Fonte da janela<select id="pipSource"></select></label><label>Proporção da janela<select id="pipAspect"><option value="16:9">16:9 · horizontal</option><option value="4:3">4:3 · laterais menores</option><option value="1:1">1:1 · quadrado</option><option value="9:16">9:16 · vertical</option></select></label><label>Canto<select id="pipCorner">'+corners+'</select></label><label>Largura da janela (%)<input id="pipSize" type="range" min="15" max="50"></label><label>Enquadramento<select id="pipFit"><option value="contain">Mostrar imagem inteira</option><option value="cover">Preencher com recorte</option></select></label><label>Cor da borda<input id="pipBorder" type="color"></label><small>PiP altera somente a imagem. O áudio da câmera é controlado no mixer. A janela fica abaixo dos GCs; o logotipo fica acima.</small></section></div><aside class="effects-preview"><h3>PRÉVIA · EDIÇÃO</h3><label class="preview-toggle"><input type="checkbox" id="fxInspect" checked> Mostrar elemento em edição, mesmo fora do AR</label><span id="fxInspectLabel">GC em edição</span><canvas id="fxDraftCanvas" width="960" height="540"></canvas><p>Base: imagem atual do AR. A prévia mostra o rascunho e o elemento que você está editando. Ativar ao aplicar controla o AR. Só Aplicar modifica a saída.</p><p id="fxStatus" role="status">Nenhuma camada ativa.</p><button id="fxBackToOperation">Voltar à operação</button></aside></div>';
function layerIndex(){return Number($('#fxLayer').value)||0}
function populateLayers(selected=0){$('#fxLayer').replaceChildren();fx.draft.layers.forEach((l,i)=>$('#fxLayer').add(new Option((i+1)+' · '+l.name,String(i))));$('#fxLayer').value=selected;}
function populatePipSources(){const select=$('#pipSource'),value=select.value;select.replaceChildren();sources.slice(0,config?.limit||10).forEach((name,i)=>select.add(new Option(name,String(i))));select.value=value||String(fx.draft.pip.source)}
function loadForm(){const l=fx.draft.layers[layerIndex()];for(const [id,key] of [['gcTitle','title'],['gcSubtitle','subtitle'],['gcCorner','corner'],['gcWidth','width'],['gcSize','size'],['gcOpacity','opacity'],['gcBackground','background'],['gcColor','color'],['gcAccent','accent']])$('#'+id).value=l[key];$('#gcOn').checked=l.on;for(const type of ['pip','logo'])for(const key of Object.keys(fx.draft[type])){const el=$('#'+type+key[0].toUpperCase()+key.slice(1));if(el){if(key==='on')el.checked=fx.draft[type][key];else el.value=fx.draft[type][key];}}}
let inspecting="gc";
function readForm(){const l=fx.draft.layers[layerIndex()];l.on=$('#gcOn').checked;for(const [id,key] of [['gcTitle','title'],['gcSubtitle','subtitle'],['gcCorner','corner'],['gcWidth','width'],['gcSize','size'],['gcOpacity','opacity'],['gcBackground','background'],['gcColor','color'],['gcAccent','accent']])l[key]=['width','size','opacity'].includes(key)?Number($('#'+id).value):$('#'+id).value;for(const type of ['pip','logo'])for(const key of Object.keys(fx.draft[type])){const el=$('#'+type+key[0].toUpperCase()+key.slice(1));if(el)fx.draft[type][key]=key==='on'?el.checked:['source','size','opacity'].includes(key)?Number(el.value):el.value;}$('#fxStatus').textContent='Ajustes pendentes. Clique em Aplicar para atualizar o AR.';}
populateLayers();populatePipSources();loadForm();$('#fxLayer').onchange=loadForm;effectsPage.querySelectorAll('.effects-editor input:not([type=file]),.effects-editor select:not(#fxLayer),.effects-editor textarea').forEach(el=>el.addEventListener('input',readForm));
function reorder(direction){readForm();const i=layerIndex(),j=Math.max(0,Math.min(fx.draft.layers.length-1,i+direction));[fx.draft.layers[i],fx.draft.layers[j]]=[fx.draft.layers[j],fx.draft.layers[i]];populateLayers(j);loadForm()};$('#gcBack').onclick=()=>reorder(-1);$('#gcFront').onclick=()=>reorder(1);
let logoLoad=0;$('#logoFile').onchange=async e=>{const id=++logoLoad,file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type)){$('#fxStatus').textContent='Use PNG, JPEG ou WebP de até 10 MB.';return}const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();if(id!==logoLoad)return;if(image.naturalWidth>8192||image.naturalHeight>8192)throw Error('Reduza o logotipo para até 8192 pixels por lado.');fx.draftLogo=image;$('#fxStatus').textContent='Logo carregado no rascunho. Marque Ativar e clique em Aplicar.';}catch(err){$('#fxStatus').textContent='Não foi possível carregar: '+err.message}finally{URL.revokeObjectURL(url)}};
$('#logoRemove').onclick=()=>{logoLoad++;fx.draftLogo=null;fx.draft.logo.on=false;$('#logoFile').value='';loadForm();$('#fxStatus').textContent='Remoção preparada. Clique em Aplicar.';};
function quickSync(){fx.live.layers.forEach((l,i)=>{const el=$('#fxGC'+i);el.textContent='GC · '+l.name;el.setAttribute('aria-pressed',l.on)});$('#fxLogo').setAttribute('aria-pressed',fx.live.logo.on);$('#fxPip').setAttribute('aria-pressed',fx.live.pip.on)}
$('#fxApply').onclick=()=>{readForm();if(fx.draft.logo.on&&!fx.draftLogo){$('#fxStatus').textContent='Carregue um logotipo antes de ativá-lo.';return}fx.live=structuredClone(fx.draft);fx.logo=fx.draftLogo;quickSync();$('#fxStatus').textContent='Ajustes aplicados à saída PROGRAM.';log('GC e efeitos aplicados ao programa')};
$('#fxDiscard').onclick=()=>{fx.draft=structuredClone(fx.live);fx.draftLogo=fx.logo;populateLayers();loadForm();$('#fxStatus').textContent='Rascunho restaurado a partir do AR.'};
for(let i=0;i<3;i++)$('#fxGC'+i).onclick=()=>{const l=fx.live.layers[i];if(!l.title.trim()&&!l.subtitle.trim()){openWorkspace('effects');$('#fxStatus').textContent='Preencha os textos e clique em Aplicar antes de colocar o GC no ar.';return}l.on=!l.on;quickSync();log(l.name+(l.on?' no AR':' retirado do AR'))};
$('#fxLogo').onclick=()=>{if(!fx.logo){openWorkspace('effects');$('#fxStatus').textContent='Carregue um logotipo e aplique os ajustes primeiro.';return}fx.live.logo.on=!fx.live.logo.on;quickSync()};$('#fxPip').onclick=()=>{fx.live.pip.on=!fx.live.pip.on;quickSync()};$('#fxClear').onclick=()=>{fx.live.layers.forEach(l=>l.on=false);fx.live.logo.on=false;fx.live.pip.on=false;quickSync();log('Todas as sobreposições retiradas do AR')};$('#fxConfigure').onclick=()=>{populatePipSources();openWorkspace('effects')};$('#fxBackToOperation').onclick=()=>openWorkspace('operation');
const effectMonitor=document.createElement('canvas');effectMonitor.className='effects-monitor';effectMonitor.width=960;effectMonitor.height=540;$('#monProgram').append(effectMonitor);const pipCanvas=document.createElement('canvas');pipCanvas.width=640;pipCanvas.height=360;
function drawFx(ctx,canvas,settings,logo,t){let pip=null;if(settings.pip.on){const i=settings.pip.source;if(i<(config?.limit||10)){const el=media[i]?.element;if(cams[i]?.conn&&el&&(el.videoWidth||el.naturalWidth||el.width)){pip=el;}else{source(pipCanvas.getContext('2d'),i,t,true);pip=pipCanvas;}}}AndromedaComposition.compose(ctx,canvas.width,canvas.height,settings,{pip,logo});}
routeProgramOutput=function(){const base=$('#monProgram canvas'),ctx=programOutput.getContext('2d');ctx.clearRect(0,0,programOutput.width,programOutput.height);ctx.drawImage(base,0,0,programOutput.width,programOutput.height);drawFx(ctx,programOutput,fx.live,fx.logo,performance.now());if(effectMonitor.width!==programOutput.width||effectMonitor.height!==programOutput.height){effectMonitor.width=programOutput.width;effectMonitor.height=programOutput.height}effectMonitor.getContext('2d').drawImage(programOutput,0,0);if(outputWindow&&!outputWindow.closed&&outputWindowCanvas){if(outputWindowCanvas.width!==programOutput.width||outputWindowCanvas.height!==programOutput.height){outputWindowCanvas.width=programOutput.width;outputWindowCanvas.height=programOutput.height}outputWindowCanvas.getContext('2d').drawImage(programOutput,0,0);}if(!effectsPage.hidden){const preview=$('#fxDraftCanvas'),pc=preview.getContext('2d');pc.drawImage(base,0,0,preview.width,preview.height);drawFx(pc,preview,inspectionSettings(),fx.draftLogo,performance.now());}};
quickSync();$('.logo-ver').textContent='LIVE · 0.12';

function inspectionSettings(){const s=structuredClone(fx.draft);if($('#fxInspect').checked){if(inspecting==='gc')s.layers[layerIndex()].on=true;else s[inspecting].on=true;}return s;}
for(const card of effectsPage.querySelectorAll('.fx-card')){const update=()=>{inspecting=card.querySelector('#pipSource')?'pip':card.querySelector('#logoFile')?'logo':'gc';$('#fxInspectLabel').textContent=({pip:'KEY 1 · PiP em edição',logo:'Logotipo em edição',gc:'GC em edição'})[inspecting];};card.addEventListener('focusin',update);card.addEventListener('pointerdown',update);card.addEventListener('input',update);}
