const keyPanel=document.createElement('div');keyPanel.className='key-panel';keyPanel.innerHTML='<div><b>KEY 1 · PiP</b><span id="keySourceLabel">Desligado</span></div><canvas id="keyMonitor" width="320" height="180"></canvas><button id="keyRelease">Retirar PiP / liberar câmera</button>';rightStage.append(keyPanel);
const previousSelect=select;select=function(bus,i){if(bus==='prv'&&fx.live.pip.on&&i===fx.live.pip.source){log('Fonte reservada ao KEY 1. Retire o PiP para liberar esta câmera no Preview.');return}previousSelect(bus,i)};
const previousSync=sync;sync=function(){if(fx.live.pip.on&&state.prv===fx.live.pip.source&&!state.busy&&state.progress===0){state.prv=cams.findIndex((c,i)=>i<(config?.limit||10)&&i!==fx.live.pip.source&&i!==state.pgm);if(state.prv<0)state.prv=10;}previousSync();$$('.mv-cell').forEach((el,i)=>{const held=fx.live.pip.on&&i===fx.live.pip.source;el.classList.toggle('key-source',held);if(held)el.querySelector('.tag').textContent='KEY 1 · PiP';});const row=$$('.bus-src')[0];if(row&&fx.live.pip.on)row.children[fx.live.pip.source].disabled=true;};
const previousQuickSync=quickSync;quickSync=function(){previousQuickSync();sync();$('#keySourceLabel').textContent=fx.live.pip.on?sources[fx.live.pip.source]+' · NO AR':'Desligado · fonte liberada';$('#keyRelease').disabled=!fx.live.pip.on;};$('#keyRelease').onclick=()=>{fx.live.pip.on=false;fx.draft.pip.on=false;loadForm();quickSync()};
const compositedRoute=routeProgramOutput;routeProgramOutput=function(){compositedRoute();const canvas=$('#keyMonitor');if(!canvas)return;const ctx=canvas.getContext('2d');if(fx.live.pip.on)source(ctx,fx.live.pip.source,performance.now(),true);else{ctx.fillStyle='#080c14';ctx.fillRect(0,0,canvas.width,canvas.height);}};quickSync();

window.andromedaKeySource=()=>fx.live.pip.on&&cams[fx.live.pip.source]?.conn?fx.live.pip.source:-1;
